"use client";

import { useState } from "react";
import { describeDecisionPolicy, type DecisionPolicy } from "@/lib/recruitment/decision-policy";
import { Select } from "./LaneEditorControls";

// docs/admission-flow.md §2, "How reports decide": four choices, no lists and no
// JSON. The sentence is generated by the same function the server decides with,
// so what a community reads while choosing is what an applicant will get.
const field =
  "w-24 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] px-2.5 py-1.5 text-[length:var(--text-body)] text-[var(--text)] focus:border-[var(--accent-1)] focus:outline-none";
const label = "text-[length:var(--text-meta)] font-medium text-[var(--text-muted)]";

export default function DecisionPolicyEditor({ initial }: { initial: DecisionPolicy }) {
  const [p, setP] = useState<DecisionPolicy>(initial);
  const set = (patch: Partial<DecisionPolicy>) => setP((prev) => ({ ...prev, ...patch }));

  return (
    <div className="flex flex-col gap-3">
      <Select
        label="They're in when"
        name="recruitmentInWhen"
        value={p.inWhen}
        onChange={(v) => set({ inWhen: v as DecisionPolicy["inWhen"] })}
        options={[
          { value: "no_no_one_yes", label: "nobody says no, and at least one says yes" },
          { value: "more_yes_than_no", label: "more say yes than no" },
          { value: "all_yes", label: "everyone says yes" },
          { value: "custom", label: "custom: at least … yes and no more than … no" },
        ]}
      />
      {p.inWhen === "custom" && (
        <div className="flex flex-wrap gap-4">
          <label className="flex flex-col gap-1">
            <span className={label}>At least this many yes</span>
            <input name="recruitmentCustomMinYes" type="number" min={0} max={50} className={field} value={p.customMinYes} onChange={(e) => set({ customMinYes: Number(e.target.value) })} />
          </label>
          <label className="flex flex-col gap-1">
            <span className={label}>No more than this many no</span>
            <input name="recruitmentCustomMaxNo" type="number" min={0} max={50} className={field} value={p.customMaxNo} onChange={(e) => set({ customMaxNo: Number(e.target.value) })} />
          </label>
        </div>
      )}
      <Select
        label="Any no, or no yes at all, means"
        name="recruitmentAnyNoMeans"
        value={p.anyNoMeans}
        onChange={(v) => set({ anyNoMeans: v as DecisionPolicy["anyNoMeans"] })}
        options={[
          { value: "wider_discussion", label: "opening a wider discussion" },
          { value: "decline", label: "declining" },
        ]}
      />
      {p.anyNoMeans === "wider_discussion" && (
        <Select
          label="…and if the discussion ends with no concern raised"
          name="recruitmentDiscussionEnds"
          value={p.discussionEnds}
          onChange={(v) => set({ discussionEnds: v as DecisionPolicy["discussionEnds"] })}
          options={[
            { value: "decline", label: "decline them" },
            { value: "admit", label: "admit them" },
          ]}
        />
      )}
      <label className="flex items-center gap-2 text-[length:var(--text-body)] text-[var(--text)]">
        <input
          type="checkbox"
          checked={p.declineOutrightAt !== null}
          onChange={(e) => set({ declineOutrightAt: e.target.checked ? 2 : null })}
        />
        Decline outright when enough say no
      </label>
      {p.declineOutrightAt !== null && (
        <label className="flex flex-col gap-1">
          <span className={label}>At least this many no</span>
          <input name="recruitmentDeclineOutrightAt" type="number" min={1} max={50} className={field} value={p.declineOutrightAt} onChange={(e) => set({ declineOutrightAt: Number(e.target.value) || 1 })} />
        </label>
      )}
      {/* An empty value clears it, which is how "off" is submitted. */}
      {p.declineOutrightAt === null && <input type="hidden" name="recruitmentDeclineOutrightAt" value="" />}
      {p.anyNoMeans === "decline" && <input type="hidden" name="recruitmentDiscussionEnds" value={p.discussionEnds} />}
      {p.inWhen !== "custom" && (
        <>
          <input type="hidden" name="recruitmentCustomMinYes" value={p.customMinYes} />
          <input type="hidden" name="recruitmentCustomMaxNo" value={p.customMaxNo} />
        </>
      )}
      <p className="border-t border-dashed border-[var(--border)] pt-2 text-[length:var(--text-body)] text-[var(--text)]">
        <span className="text-[var(--text-muted)]">What happens: </span>
        {describeDecisionPolicy(p)}
      </p>
    </div>
  );
}
